    private int ActiveTab = 1;
    private string _searchHocBa = "";
    private string SearchHocBa { get => _searchHocBa; set { _searchHocBa = value; } }

    private List<HocBaItem> ListHocBa = new();
    private List<HocBaItem> PagedHocBaList => ListHocBa.Where(x => string.IsNullOrEmpty(SearchHocBa) || x.TenHocSinh.Contains(SearchHocBa, StringComparison.OrdinalIgnoreCase)).ToList();
    private bool IsAllHocBaSelected => PagedHocBaList.Any() && PagedHocBaList.All(x => x.IsSelected);

    private List<GoiTinItem> ListGoiTin = new();

    protected override void OnInitialized()
    {
        for (int i = 1; i <= 5; i++) ListHocBa.Add(new HocBaItem { STT = i, MaDinhDanh = $"HS202400{i}", TenHocSinh = $"Học Sinh {i}" });
    }

    private void SwitchTab(int tab) => ActiveTab = tab;
    private void ToggleSelectAllHocBa(ChangeEventArgs e) { bool isChecked = (bool)(e.Value ?? false); foreach (var item in PagedHocBaList) item.IsSelected = isChecked; }

    private void TaoGoiTinMoi()
    {
        var selected = ListHocBa.Where(x => x.IsSelected).ToList();
        if (!selected.Any()) return;

        ListGoiTin.Insert(0, new GoiTinItem { STT = ListGoiTin.Count + 1, TenGoi = $"Gói tin {DateTime.Now:HH:mm:ss}", NguoiTao = "Admin", NgayTao = DateTime.Now, SoLuong = selected.Count });
        ListHocBa.RemoveAll(x => x.IsSelected); // Đóng gói xong thì biến mất khỏi list Chưa đóng gói
        ActiveTab = 2; // Chuyển sang tab quản lý gói tin
    }

    private class HocBaItem { public bool IsSelected { get; set; } public int STT { get; set; } public string MaDinhDanh { get; set; } = ""; public string TenHocSinh { get; set; } = ""; }
    private class GoiTinItem { public int STT { get; set; } public string TenGoi { get; set; } = ""; public string NguoiTao { get; set; } = ""; public DateTime NgayTao { get; set; } public int SoLuong { get; set; } }

